/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import runQueue, { readLimit } from './dist/queue.js';
import { submit } from './dist/caller.js';
const makeJobs = () => [ {id:'a',priority:1}, {id:'b',priority:2}, {id:'c',priority:3}, {id:'d',priority:4} ];
assert.equal(readLimit('0'), 3);
const pausedSaves=[];
assert.equal(await submit(makeJobs(), async j => { pausedSaves.push(j.id); }), 'finished');
assert.deepEqual(pausedSaves, ['a','b','c']);
console.log('CONFIRMED pause violation: readLimit(\"0\") = 3; submit saves a,b,c and returns finished.');
const starts=[], finishes=[], releases=[];
await runQueue(makeJobs(), '2', j => { starts.push(j.id); return new Promise(resolve => { releases.push(() => { finishes.push(j.id); resolve(); }); }); });
assert.deepEqual(starts,['a','b']);
assert.deepEqual(finishes,[]);
console.log('CONFIRMED sequencing/completion violation: both selected saves started; runQueue resolved with neither save complete.');
for (const release of releases) release();
await Promise.resolve();
const jobs=[{id:'high',priority:9},{id:'low',priority:1}];
await runQueue(jobs, '1', async () => {});
assert.deepEqual(jobs.map(j=>j.id),['low','high']);
console.log('CONFIRMED ownership violation: caller array reordered from high,low to low,high.');
const child=spawnSync(process.execPath,['--unhandled-rejections=strict','--input-type=module','-e', "'`
import runQueue from '"'./dist/queue.js';
await runQueue([{id:'a',priority:1},{id:'b',priority:2}], '2', async job => {
 console.log('started',job.id);
 if(job.id==='a') throw new Error('save failed');
}).then(() => console.log('queue resolved'), () => console.log('queue rejected'));
"'`],{encoding:'"'utf8'});
assert.notEqual(child.status,0);
assert.match(child.stdout,/started a\\nstarted b\\nqueue resolved/);
assert.match(child.stderr,/Error: save failed/);
console.log('CONFIRMED failure violation: later save started, queue resolved, child exited '+child.status+' on unhandled save failure.');
console.log('Focused reproductions: 4/4 confirmed.');
NODE"

